QUESTIONS = [
    {'difficulty': 'EASY', 'question_text': 'What is C? What are its main features and why is it still used?', 'expected_answer': 'C is a general-purpose, procedural, statically typed, compiled language created by Dennis Ritchie in the early 1970s. Features: small core language, direct memory access through pointers, efficient and predictable code, portability across platforms, and a standard library for I/O, strings and memory. It remains the main language for operating systems, device drivers, embedded firmware, databases and language runtimes because it gives precise control over memory and hardware with little overhead and no runtime.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon', 'Microsoft']},
    {'difficulty': 'EASY', 'question_text': 'What are the stages of compiling a C program?', 'expected_answer': '', 'companies': ['Zoho', 'Oracle', 'Microsoft', 'Amazon', 'Goldman Sachs']},
    {'difficulty': 'EASY', 'question_text': 'Preprocessing: handles #include, #define and conditional compilation, producing expanded source. 2. Compilation: translates the source into assembly (syntax and type checking, optimization). 3. Assembly: converts assembly into relocatable object code (.o files). 4. Linking: combines object files and libraries, resolving symbols into an executable. Errors map to stages: syntax and type errors come from compilation, and "undefined reference" errors come from linking. 3. What are the basic data types in C and what does sizeof return?', 'expected_answer': 'Basic types: char, short, int, long, long long, float, double, long double (plus _Bool in C99), with signed / unsigned modifiers. Their sizes are implementation defined (the standard guarantees only minimum ranges and that sizeof(char) is 1), so for exact widths use <stdint.h> types such as int32_t. sizeof is a compile-time operator (except for variable length arrays) that returns the size in bytes as a size_t.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon', 'Microsoft']},
    {'difficulty': 'EASY', 'question_text': 'What is the difference between a declaration and a definition? What does extern do?', 'expected_answer': 'A declaration tells the compiler a name and its type exist; a definition also allocates storage (or provides the function body). A name may be declared many times but defined once. extern declares a variable or function that is defined elsewhere (another file), without allocating storage, which is how global variables are shared across translation units.', 'companies': ['Zoho', 'Oracle', 'Microsoft', 'Flipkart']},
    {'difficulty': 'EASY', 'question_text': 'What are the storage classes in C?', 'expected_answer': 'auto: the default for local variables; automatic storage on the stack, uninitialized (garbage) unless set. register: a hint to keep the variable in a CPU register; you cannot take its address. static: a local keeps its value between calls (static storage, zero-initialized); at file scope it gives internal linkage (visible only in that file). extern: refers to an object defined elsewhere (external linkage). C11 adds _Thread_local for per-thread storage.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon', 'Goldman Sachs']},
    {'difficulty': 'EASY', 'question_text': 'Explain operator precedence, associativity and the difference between pre- and post-increment.', 'expected_answer': 'Precedence decides which operator binds tighter (* before +), and associativity resolves equal precedence (left to right for most binary operators, right to left for assignment and unary operators). ++x increments first and yields the new value; x++ yields the old value and increments afterward. Modifying a variable more than once in an expression without a sequence point (for example i = i++ + ++i) is undefined behavior. Also remember that && and || short-circuit and evaluate left to right.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon']},
    {'difficulty': 'EASY', 'question_text': 'What are implicit type conversion, type casting and integer promotion?', 'expected_answer': 'When types are mixed in an expression, C applies the usual arithmetic conversions: operands smaller than int are promoted to int (integer promotion), then converted to the "larger" type (int to long to float to double). Mixing signed and unsigned of the same rank converts to unsigned, which can produce surprising comparisons (a negative number becomes huge). An explicit cast (type)expr forces a conversion; narrowing conversions can lose data, and converting a float to an integer truncates toward zero.', 'companies': ['Zoho', 'Oracle', 'Amazon', 'Microsoft', 'Goldman Sachs']},
    {'difficulty': 'EASY', 'question_text': 'How do break, continue and switch work? What is switch fall-through?', 'expected_answer': 'break exits the nearest loop or switch; continue skips to the next loop iteration. In a switch, execution jumps to the matching case label and keeps running into following cases until a break (this is fall-through, sometimes intentional, often a bug). The switch expression must be an integer type and case labels must be constant expressions. do- while always runs its body at least once, while while may run zero times.', 'companies': ['Zoho', 'Oracle', 'Flipkart']},
    {'difficulty': 'EASY', 'question_text': 'How are arrays stored in C? Is there bounds checking?', 'expected_answer': 'An array is a contiguous block of elements of the same type, indexed from 0. C performs no bounds checking: reading or writing out of range is undefined behavior and a major source of crashes and security bugs. In most expressions an array name decays to a pointer to its first element, and a[i] is defined as *(a + i). Arrays cannot be assigned or compared with = or ==, and when passed to a function they are passed as pointers, so the size must be passed separately.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon', 'Microsoft']},
    {'difficulty': 'EASY', 'question_text': 'How are strings represented in C? What is the difference between a character array and a string literal?', 'expected_answer': 'A string is a sequence of char ending with the null terminator \'\\0\'; there is no built-in string type. A character array initialized from a literal (char s[] = "hi") is a modifiable copy on the stack; a pointer to a literal (char *p = "hi") points to read-only memory, and modifying it is undefined behavior (prefer const char *). Forgetting the terminator or room for it is the classic cause of string bugs.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon', 'Microsoft']},
    {'difficulty': 'EASY', 'question_text': 'What is a pointer? What are null, void and wild pointers?', 'expected_answer': 'A pointer is a variable that holds a memory address. & takes an address and * dereferences it. A null pointer points to nothing (compare against NULL) and dereferencing it is undefined behavior. A void pointer (void *) is a generic pointer with no type, which must be cast (or converted) before dereferencing and cannot be used in arithmetic in standard C. A wild pointer is an uninitialized pointer holding an indeterminate address. Initialize pointers to NULL or a valid address.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon', 'Microsoft', 'Goldman Sachs']},
    {'difficulty': 'EASY', 'question_text': 'What is the difference between call by value and call by reference in C?', 'expected_answer': 'C always passes arguments by value: the function gets a copy, so changing the parameter does not change the caller\'s variable. To let a function modify the caller\'s data, you pass the address (a pointer), which is a copy of the address but still refers to the same object; this is how "call by reference" is simulated. Arrays are passed as pointers, so changes to elements are visible to the caller.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon']},
    {'difficulty': 'EASY', 'question_text': 'What is recursion? What are its costs?', 'expected_answer': 'Recursion is a function calling itself, needing a base case to stop and progress toward it. Each call pushes a stack frame (return address, parameters, locals), so deep recursion consumes stack space and can cause a stack overflow, and function call overhead makes it slower than an equivalent loop. Some compilers perform tail-call optimization when the recursive call is the last operation, but C does not guarantee it.', 'companies': ['Zoho', 'Oracle', 'Amazon', 'Flipkart', 'Microsoft']},
    {'difficulty': 'EASY', 'question_text': 'What is the difference between a structure and a union?', 'expected_answer': 'A struct allocates separate storage for each member, so its size is at least the sum of the members (plus padding). A union stores all members in the same memory, so its size is that of the largest member and only one member holds a meaningful value at a time. Unions save memory and are used for variant data, hardware register views and low-level conversions; reading a member other than the one last written has restrictions (it is allowed for type punning in C but undefined in C++).', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon', 'Microsoft']},
    {'difficulty': 'EASY', 'question_text': 'What are typedef and enum?', 'expected_answer': 'typedef creates an alias for an existing type (for example for a struct, a function pointer or a fixed-width integer), improving readability and portability; it does not create a new type. enum defines a set of named integer constants (starting at 0 by default, incrementing by 1), which makes code self-documenting. In C, enum constants are plain integers, so there is little type safety compared with C++ scoped enums.', 'companies': ['Zoho', 'Oracle', 'Flipkart']},
    {'difficulty': 'EASY', 'question_text': 'What does the C preprocessor do? Explain #define, #include, conditional compilation and header guards.', 'expected_answer': 'The preprocessor runs before compilation and performs text substitution. #define creates constants and macros; #include pastes in a header (angle brackets search system directories, quotes search the local directory first); #ifdef, #ifndef, #if and #endif select code at compile time (platform or debug builds). Header guards (#ifndef NAME / #define NAME / #endif, or #pragma once) prevent a header from being included twice in the same translation unit.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon', 'Microsoft']},
    {'difficulty': 'EASY', 'question_text': 'What are malloc, calloc, realloc and free? How do they differ?', 'expected_answer': 'They manage heap memory from <stdlib.h>. malloc(n) allocates n bytes uninitialized; calloc(count, size) allocates and zero-initializes (and checks for multiplication overflow); realloc(p, n) resizes a block and may move it (returning a new pointer); free(p) releases memory. All allocation functions can return NULL on failure, so always check. Each allocated block must be freed exactly once; freeing twice, or using memory after free, is undefined behavior.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon', 'Goldman Sachs', 'Microsoft']},
    {'difficulty': 'EASY', 'question_text': 'What is the memory layout of a C program?', 'expected_answer': 'A process typically has these segments: text (executable code, usually read-only), initialized data (globals and statics with non-zero initial values), BSS (uninitialized or zero- initialized globals and statics), the heap (dynamic allocation, grows upward) and the stack (function frames and locals, grows downward on most architectures). String literals usually live in read-only data. Knowing this explains lifetime, initial values and many crashes.', 'companies': ['Zoho', 'Oracle', 'Goldman Sachs', 'Amazon', 'Microsoft', 'Google']},
    {'difficulty': 'EASY', 'question_text': 'How does file handling work in C? What are the file modes?', 'expected_answer': 'The standard library uses FILE * streams: fopen opens a file and returns NULL on failure, fclose closes it, and fread / fwrite / fprintf / fscanf / fgets / fputs transfer data. Modes: "r" read, "w" write (truncates), "a" append, with + for update and b for binary (it matters on some platforms). Always check return values, and close files to flush buffers and release resources. Text mode may translate newlines on some systems, binary mode does not.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Microsoft']},
    {'difficulty': 'EASY', 'question_text': 'How do printf and scanf work? Why is gets dangerous?', 'expected_answer': 'printf writes formatted output using format specifiers (%d, %u, %f, %c, %s, %p, %x, %zu for size_t) and returns the number of characters written; mismatched specifiers and arguments are undefined behavior. scanf reads formatted input into addresses (so you pass &x), returns the number of items successfully read (check it), and can leave unread characters (such as a newline) in the buffer. gets has no way to limit input size, so it causes buffer overflows; it was removed in C11, and fgets with a size limit is the safe replacement.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon', 'Microsoft']},
    {'difficulty': 'MEDIUM', 'question_text': 'Explain pointer arithmetic. How do arrays decay to pointers, and how does sizeof differ for an array and a pointer?', 'expected_answer': 'Adding an integer n to a pointer moves it by n * sizeof(*p) bytes, so p + 1 points to the next element of its type; subtracting two pointers into the same array gives the number of elements between them (a ptrdiff_t). Arithmetic is only defined within an array (or one past its end). An array name decays to a pointer to its first element in most expressions, except as the operand of sizeof or unary &: sizeof(arr) is the total size of the array in bytes, while sizeof(ptr) is just the size of the pointer. This is why a function receiving an array parameter cannot know its length, since the parameter is really a pointer.', 'companies': ['Zoho', 'Oracle', 'Microsoft', 'Amazon', 'Goldman Sachs', 'Google']},
    {'difficulty': 'MEDIUM', 'question_text': 'What do const int *p, int * const p and const int * const p mean?', 'expected_answer': 'Read the declaration from right to left. const int *p (or int const *p): a pointer to a constant integer; the data cannot be changed through p, but p can point elsewhere. int * const p: a constant pointer to an integer; p cannot be reassigned, but the data can change. const int * const p: neither can change. Using const for read-only parameters documents intent, allows the compiler to catch mistakes and lets string literals be passed safely as const char *.', 'companies': ['Zoho', 'Oracle', 'Microsoft', 'Amazon', 'Flipkart']},
    {'difficulty': 'MEDIUM', 'question_text': 'What are function pointers? Where are they used?', 'expected_answer': 'A function pointer holds the address of a function, with a type that includes the return type and parameter types. It enables callbacks (for example the comparison function passed to qsort), dispatch tables and state machines, plugin and driver interfaces, and a way to simulate polymorphism in C. Using a typedef for the function pointer type keeps declarations readable. Calling through a pointer is an indirect call, so it is slightly slower and harder for the compiler to inline.', 'companies': ['Zoho', 'Oracle', 'Microsoft', 'Amazon', 'Goldman Sachs']},
    {'difficulty': 'MEDIUM', 'question_text': 'What are dangling pointers, memory leaks, double free and use-after-free? How do you detect them?', 'expected_answer': "A dangling pointer refers to memory that was freed or whose scope ended (for example the address of a local variable returned from a function). A memory leak is allocated memory that is never freed, so usage grows over time. Double free frees the same block twice, corrupting the allocator's bookkeeping, and use-after-free accesses a block after freeing it; both are undefined behavior and common security vulnerabilities. Prevention: set pointers to NULL after free, define clear ownership rules, pair every allocation with one release path, and use cleanup patterns. Detection: Valgrind, AddressSanitizer, LeakSanitizer, static analyzers and careful code review.", 'companies': ['Oracle', 'Microsoft', 'Amazon', 'Goldman Sachs', 'Google', 'Meta', 'Zoho']},
    {'difficulty': 'MEDIUM', 'question_text': 'Compare stack and heap memory. What causes stack overflow and heap fragmentation?', 'expected_answer': 'The stack stores local variables and call frames; allocation and release are automatic and extremely fast, but the size is limited (often 1 to 8 MB per thread). Stack overflow comes from runaway recursion or very large local arrays. The heap is managed manually through malloc and free; it is flexible in size and lifetime but slower, and repeated allocation and release of different sizes causes fragmentation (free memory split into pieces too small to use). Embedded systems often avoid the heap entirely and use static allocation or fixed-size pools for predictability.', 'companies': ['Oracle', 'Zoho', 'Goldman Sachs', 'Amazon', 'Microsoft']},
    {'difficulty': 'MEDIUM', 'question_text': 'What are the pitfalls of dynamic memory allocation? Should you cast the result of malloc?', 'expected_answer': "Always check for NULL; malloc(0) may return NULL or a unique pointer (implementation defined); compute sizes carefully to avoid integer overflow (which calloc guards against); and with realloc, assign the result to a temporary variable first, because on failure it returns NULL and the original block is still valid (overwriting the original pointer would leak it). In C you should not cast the result of malloc: void * converts implicitly, and a cast can hide a missing #include <stdlib.h> on older compilers. (C++ requires the cast.) Prefer sizeof *p over sizeof(type) so the size follows the pointer's type.", 'companies': ['Zoho', 'Oracle', 'Amazon', 'Microsoft', 'Goldman Sachs']},
    {'difficulty': 'MEDIUM', 'question_text': 'What is structure padding and alignment? How can you reduce wasted space?', 'expected_answer': "CPUs access data most efficiently (or only correctly) at addresses that are multiples of the type's size, so compilers insert padding bytes between members and at the end of a struct so that each member is aligned and arrays of structs stay aligned. Therefore sizeof(struct) can exceed the sum of its members. Ordering members from largest to smallest alignment usually minimizes padding. Compilers offer packing options (#pragma pack, __attribute__((packed))), but packed structs can cause slower or faulting unaligned access and are non-portable. Use offsetof to inspect layout.", 'companies': ['Zoho', 'Oracle', 'Goldman Sachs', 'Amazon', 'Microsoft', 'Google']},
    {'difficulty': 'MEDIUM', 'question_text': 'What are unions used for? What is endianness?', 'expected_answer': 'Unions share storage between members, used for variant records (tagged unions), saving memory, and viewing the same bytes in different ways (for example a register as a whole word or as fields). Endianness is the byte order in which multi-byte values are stored: little-endian (least significant byte at the lowest address, as on x86 and most ARM systems) or big-endian (most significant byte first, as in network byte order). It matters when reading binary files, communicating over networks (htonl / ntohl) or interfacing with hardware, and it is why viewing an int as bytes is not portable.', 'companies': ['Zoho', 'Oracle', 'Microsoft', 'Amazon', 'Goldman Sachs']},
    {'difficulty': 'MEDIUM', 'question_text': 'What are bitwise operators and bit fields used for?', 'expected_answer': "Bitwise operators (&, |, ^, ~, <<, >>) work on individual bits: setting a bit uses OR with a mask, clearing uses AND with the inverted mask, toggling uses XOR, and testing uses AND. They are used for flags, hardware registers, compact data, hashing and fast arithmetic tricks. Bit fields (unsigned flag : 1;) let a struct member occupy a specified number of bits, but their layout, ordering and signedness are implementation defined, so they are unreliable for portable binary formats. Right-shifting a negative signed value is implementation defined, and shifting by the type's width or more is undefined.", 'companies': ['Zoho', 'Oracle', 'Goldman Sachs', 'Amazon', 'Microsoft', 'Google']},
    {'difficulty': 'MEDIUM', 'question_text': 'What do volatile and const mean? Can a variable be both?', 'expected_answer': 'const means the program must not modify the object through that name. volatile tells the compiler the value may change outside normal program flow (hardware registers, memory-mapped I/O, variables changed by a signal handler or an interrupt service routine), so every read and write must actually happen and cannot be cached in a register or optimized away. A variable can be both: for example a read-only status register is const volatile. Importantly, volatile does not provide atomicity, ordering between threads or mutual exclusion; use C11 atomics or locks for that.', 'companies': ['Goldman Sachs', 'Microsoft', 'Amazon', 'Oracle', 'Zoho']},
    {'difficulty': 'MEDIUM', 'question_text': 'What are the pitfalls of macros? Compare macros, inline functions and static inline.', 'expected_answer': 'Macros are textual substitutions, so they have no type checking, are hard to debug, and arguments with side effects may be evaluated more than once (a squaring macro called with an incrementing argument misbehaves). Always parenthesize parameters and the whole expression. The # operator turns an argument into a string and ## pastes tokens. An inline function (C99) is type checked and evaluated once; static inline in a header gives each translation unit its own copy and avoids linker problems, and is the usual way to replace small function-like macros. inline is only a hint to the compiler.', 'companies': ['Zoho', 'Oracle', 'Microsoft', 'Amazon', 'Flipkart', 'Goldman Sachs']},
    {'difficulty': 'MEDIUM', 'question_text': 'What are internal and external linkage? How should you organize headers and source files?', 'expected_answer': 'Each .c file with its included headers is a translation unit. Names with external linkage (non-static globals and functions) are visible to other units through the linker; names with internal linkage (static at file scope) are private to the unit, which avoids collisions and enables optimization. Headers should contain declarations (function prototypes, type definitions, extern declarations) with include guards, and source files contain definitions. Defining a global variable in a header included by many files causes "multiple definition" linker errors.', 'companies': ['Zoho', 'Oracle', 'Microsoft', 'Amazon', 'Google']},
    {'difficulty': 'MEDIUM', 'question_text': 'What is the difference between static and dynamic libraries? What causes "undefined reference" errors?', 'expected_answer': 'A static library (.a, .lib) is archived object code copied into the executable at link time: self-contained but larger, and updating the library requires relinking. A dynamic (shared) library (.so, .dll, .dylib) is loaded at run time and shared among processes: smaller executables and shared updates, but dependence on the correct version being present. "Undefined reference" means the linker found a declaration but no definition: a missing source file or library (-l), wrong link order, a typo, or a missing extern "C" when mixing C and C++.', 'companies': ['Microsoft', 'Amazon', 'Oracle', 'Goldman Sachs', 'Google']},
    {'difficulty': 'MEDIUM', 'question_text': 'How do variadic functions work ( stdarg.h)? How does printf use them?', 'expected_answer': 'A variadic function declares ... after at least one named parameter and accesses the extra arguments through the macros va_start, va_arg, va_end (and va_copy). The compiler does not know the number or types of the extra arguments, so the function must learn them some other way (the format string for printf, or a count or sentinel). Passing arguments that do not match what the function reads is undefined behavior, which is why format-string mismatches are bugs and why attacker-controlled format strings are vulnerabilities. Small types are promoted when passed through ... (float to double, char and short to int).', 'companies': ['Zoho', 'Oracle', 'Microsoft', 'Amazon']},
    {'difficulty': 'MEDIUM', 'question_text': 'What are the common string function pitfalls ( strcpy, strncpy, strlen vs sizeof)?', 'expected_answer': 'strcpy and strcat do not check destination size, so they overflow buffers. strncpy limits the count but does not guarantee a null terminator if the source is long, and it pads with zeros if the source is short, so it is easy to misuse. Safer options: snprintf, strlcpy (where available) or manual length checks. strlen counts characters up to the terminator at run time (excluding it), while sizeof on an array gives its total size in bytes (including the terminator) and on a pointer gives the pointer size. strcmp returns zero when strings are equal, not true.', 'companies': ['Zoho', 'Oracle', 'Amazon', 'Microsoft', 'Goldman Sachs']},
    {'difficulty': 'MEDIUM', 'question_text': 'What are undefined, unspecified and implementation-defined behavior? Give examples.', 'expected_answer': 'Undefined behavior (UB): the standard imposes no requirements, so anything may happen (examples: out-of-bounds access, dereferencing null, signed integer overflow, using an uninitialized variable, modifying a variable twice between sequence points, violating strict aliasing). Unspecified behavior: the compiler may choose among valid options without documenting it (for example the order in which function arguments are evaluated). Implementation-defined behavior: the choice must be documented (for example the size of int or the result of right-shifting a negative number). Compilers assume UB never occurs and optimize on that assumption, so a program with UB may break only at higher optimization levels.', 'companies': ['Google', 'Meta', 'Goldman Sachs', 'Microsoft', 'Amazon', 'Oracle']},
    {'difficulty': 'MEDIUM', 'question_text': 'How do integer overflow and signed versus unsigned comparisons cause bugs?', 'expected_answer': 'Unsigned overflow wraps around modulo 2^n (well defined), while signed overflow is undefined behavior, so a compiler may remove an overflow check that relies on wrapping. When a signed and an unsigned value of the same rank are compared, the signed one is converted to unsigned, so -1 < 1u is false. Typical bugs: loops that count down with an unsigned index (never going below zero), size calculations such as count * size that overflow before allocation, and truncation when assigning a wider type to a narrower one. Use checks before arithmetic, wider types and the appropriate size_t / ptrdiff_t types.', 'companies': ['Goldman Sachs', 'Google', 'Microsoft', 'Amazon', 'Meta', 'Zoho']},
    {'difficulty': 'MEDIUM', 'question_text': 'How does buffered I/O work? What do fflush, errno and perror do?', 'expected_answer': 'The C library buffers streams for efficiency: stdout is typically line buffered when attached to a terminal and fully buffered when redirected to a file or pipe, stderr is unbuffered, and data is written when the buffer fills, on newline (for line buffering), at fflush or fclose, or at normal program exit. If a program crashes before flushing, buffered output can be lost, which explains missing debug prints. errno is a thread-local error code set by failing library or system calls (check the return value first, then errno); perror and strerror turn it into a message.', 'companies': ['Oracle', 'Microsoft', 'Amazon', 'Zoho']},
    {'difficulty': 'MEDIUM', 'question_text': 'How do command-line arguments work? What is the difference between exit, return and abort?', 'expected_answer': 'main can be declared as int main(int argc, char *argv[]): argc is the argument count (including the program name) and argv is an array of strings terminated by a null pointer. return from main ends the program with that status and is equivalent to calling exit. exit terminates the whole program from anywhere, flushing and closing streams and running atexit handlers. abort terminates abnormally by raising SIGABRT without normal cleanup, often producing a core dump. A status of 0 (EXIT_SUCCESS) conventionally means success.', 'companies': ['Zoho', 'Oracle', 'Flipkart', 'Amazon', 'Microsoft']},
    {'difficulty': 'MEDIUM', 'question_text': 'Compare arrays and linked lists. How do you build generic containers in C?', 'expected_answer': 'An array gives O(1) random access, compact storage and excellent cache behavior, but fixed size (or costly resizing) and O(n) insertion or deletion in the middle. A linked list gives O(1) insertion and deletion when you hold the node, dynamic growth, but O(n) access, extra pointer overhead per element and poor cache locality; doubly linked lists allow backward traversal. Since C has no templates, generic containers use void * for data (losing type safety, with the caller managing casting and ownership), macros that generate type-specific code, or function pointers for comparison, copy and destroy operations. Intrusive lists (the link embedded in the data struct, as in the Linux kernel) avoid separate node allocations.', 'companies': ['Flipkart', 'Amazon', 'Goldman Sachs', 'Microsoft', 'Zoho', 'Oracle']},
    {'difficulty': 'HARD', 'question_text': 'What is the strict aliasing rule? What are type punning and restrict?', 'expected_answer': "The strict aliasing rule says an object may only be accessed through an lvalue of a compatible type (or a character type); accessing a float through an int * is undefined behavior. Compilers use this to assume pointers of different types do not overlap, which lets them reorder and cache loads and stores, so violating it can produce code that works at -O0 and breaks at -O2. Safe type punning uses memcpy into an object of the target type (compilers optimize it away), a union (permitted in C), or char access. restrict (C99) is a promise from the programmer that, for the pointer's lifetime, the pointed-to object is accessed only through that pointer, enabling optimizations (as in memcpy versus memmove); breaking the promise is undefined behavior.", 'companies': ['Google', 'Meta', 'Goldman Sachs', 'Microsoft', 'Amazon']},
    {'difficulty': 'HARD', 'question_text': 'What are sequence points and evaluation order? Why are some expressions undefined?', 'expected_answer': 'A sequence point (C11 terminology: "sequenced before" relationships) is a point at which all side effects of earlier evaluations are complete. Examples: the end of a full expression, the &&, ||, ?: and comma operators, and function calls (after the arguments are evaluated). Between sequence points, modifying an object more than once, or modifying it and reading it for anything other than computing the new value, is undefined behavior (as in assigning to an element using an index that also increments in the same expression). The order of evaluation of function arguments and of operands of most operators is unspecified, so code must not depend on it.', 'companies': ['Google', 'Goldman Sachs', 'Microsoft', 'Oracle', 'Zoho']},
    {'difficulty': 'HARD', 'question_text': 'How do compiler optimizations interact with undefined behavior? Why can code behave differently at different optimization levels?', 'expected_answer': 'Optimizers are allowed to assume the program never invokes UB, so they delete checks and transform code based on that assumption: a null check after a dereference may be removed, a loop with signed overflow may be assumed to terminate, and unreachable paths may be pruned. Uninitialized reads may take different values in different places. Consequently UB bugs frequently appear only when optimization is turned on, when the compiler version changes, or after unrelated edits. Defenses: sanitizers (UBSan, ASan, MSan), compiler warnings (-Wall -Wextra), static analysis, testing at several optimization levels and avoiding clever code that relies on implementation behavior.', 'companies': ['Google', 'Meta', 'Goldman Sachs', 'Microsoft']},
    {'difficulty': 'HARD', 'question_text': 'How does a function call work at the machine level? Explain stack frames, calling conventions and the ABI.', 'expected_answer': 'A calling convention (part of the platform ABI) defines how arguments are passed (registers first on x86-64 and ARM, then the stack), where the return value goes, which registers the caller or callee must preserve, and stack alignment. On a call the return address is pushed (or saved in a link register), the callee builds a stack frame holding saved registers, local variables and sometimes spilled arguments, and on return the frame is torn down. Understanding frames explains recursion depth, why returning a pointer to a local is a bug, how debuggers produce backtraces and how stack buffer overflows overwrite the return address. Variadic functions and structure passing have special rules.', 'companies': ['Google', 'Microsoft', 'Amazon', 'Goldman Sachs', 'Oracle']},
    {'difficulty': 'HARD', 'question_text': 'How does malloc work internally? What are brk/mmap, free lists, arenas and fragmentation?', 'expected_answer': 'Allocators request large regions from the kernel (brk / sbrk to extend the heap, mmap for big allocations) and carve them into blocks. Each block typically has a small header recording its size and state, and freed blocks go onto free lists or size-class bins so they can be reused; adjacent free blocks are coalesced to fight external fragmentation, while rounding sizes up causes internal fragmentation. Modern allocators (glibc ptmalloc, jemalloc, tcmalloc) use per-thread arenas or caches to reduce lock contention. Memory is not always returned to the OS at free. Overflowing a block can corrupt the neighboring headers, which is why heap corruption often crashes later, far from the bug.', 'companies': ['Google', 'Meta', 'Goldman Sachs', 'Amazon', 'Microsoft', 'Oracle']},
    {'difficulty': 'HARD', 'question_text': 'How does virtual memory work? What causes a segmentation fault?', 'expected_answer': 'Each process sees a private virtual address space that the hardware MMU maps to physical memory in pages (typically 4 KB) via page tables, with a TLB caching translations. Pages have permissions (read, write, execute) and may be swapped out or mapped lazily (demand paging), so allocation can succeed without physical memory being committed until first touch. A segmentation fault occurs when a process accesses an unmapped address or violates permissions (dereferencing null, writing to read-only memory such as a string literal, executing non-executable memory, stack overflow into a guard page); the kernel sends SIGSEGV. Memory mapping also underlies shared libraries, files via mmap and copy-on-write after fork.', 'companies': ['Google', 'Microsoft', 'Amazon', 'Oracle', 'Goldman Sachs', 'Meta']},
    {'difficulty': 'HARD', 'question_text': 'How do endianness, alignment and fixed-width types affect portability?', 'expected_answer': 'The sizes of int, long and pointers differ between platforms (for example long is 64- bit on Linux x86-64 but 32-bit on 64-bit Windows), so use <stdint.h> types (uint32_t, int64_t, uintptr_t) and size_t for sizes. Binary formats and network protocols need explicit byte order handling (convert with htonl / ntohl or shifts) rather than casting a struct over a buffer, which also risks misaligned access (slow on some CPUs, a fault or trap on others) and struct padding differences. Also do not assume char is signed or unsigned, and avoid relying on bit field layout. Portable code isolates these assumptions behind well-tested helper functions.', 'companies': ['Goldman Sachs', 'Amazon', 'Microsoft', 'Google', 'Oracle']},
    {'difficulty': 'HARD', 'question_text': 'How does concurrency work in C? Explain pthreads, mutexes, data races, deadlock and C11 atomics.', 'expected_answer': 'Before C11 the language had no threads, so POSIX threads (pthreads) or OS APIs were used; C11 adds <threads.h>, <stdatomic.h> and a memory model. A data race (unsynchronized concurrent access where at least one is a write) is undefined behavior. Protect shared data with mutexes, use condition variables to wait for conditions (checking them in a loop because of spurious wakeups), and prevent deadlock with consistent lock ordering and short critical sections. Atomics provide indivisible operations and ordering (memory_order_seq_cst by default, with acquire/release and relaxed variants for experts). volatile is not a synchronization tool. Also consider thread-local storage (_Thread_local) and false sharing between cache lines.', 'companies': ['Goldman Sachs', 'Google', 'Amazon', 'Microsoft', 'Meta']},
    {'difficulty': 'HARD', 'question_text': 'What are reentrancy, thread safety and async-signal safety? What can you do in a signal handler?', 'expected_answer': 'A function is reentrant if it can be safely re-entered (interrupted and called again before the first call finishes) because it uses only its arguments and local data; functions using static buffers or global state (like strtok, rand, or asctime) are not. Thread-safe means correct when called concurrently from threads (usually via locks or thread-local data). Async-signal-safe functions are the small set (such as write, _exit, signal- related calls) that may be called from a signal handler, because the handler can interrupt the program at any point, including inside malloc or printf, so calling non-safe functions can deadlock or corrupt state. Standard practice is to set a volatile sig_atomic_t flag in the handler and do the real work in the main loop.', 'companies': ['Oracle', 'Microsoft', 'Amazon', 'Goldman Sachs', 'Google']},
    {'difficulty': 'HARD', 'question_text': 'How does linking work in depth? Explain symbols, weak symbols, object file sections, PIC and the GOT/PLT.', 'expected_answer': 'Object files (ELF on Linux) contain sections (.text code, .data, .bss, .rodata) and a symbol table of defined and undefined symbols plus relocation entries. The linker resolves undefined symbols, merges sections, assigns addresses and applies relocations. Strong and weak symbols let a library provide a default definition that a user definition overrides. Shared libraries are compiled as position-independent code (PIC) so they can load at any address; calls to external functions go through the PLT (procedure linkage table) and GOT (global offset table), which enables lazy binding. Understanding this explains symbol interposition (LD_PRELOAD), duplicate symbol errors, link order and static initialization behavior.', 'companies': ['Google', 'Microsoft', 'Oracle', 'Amazon', 'Goldman Sachs']},
    {'difficulty': 'HARD', 'question_text': 'What advanced preprocessor and C11 features exist (X-macros, _Generic, _Static_assert)?', 'expected_answer': "X-macros define a list of items once in a macro and expand it several ways (enum values, name strings, tables), avoiding mismatched lists. _Generic (C11) selects an expression based on the type of its controlling operand, enabling type-generic macros (like <tgmath.h>). _Static_assert checks conditions at compile time (struct sizes, enum ranges), and _Alignas / _Alignof, _Noreturn and anonymous structs and unions are other C11 additions. The preprocessor's power is also a hazard: heavy macro use harms readability, debugging and tooling, so use it for what the language cannot do directly.", 'companies': ['Google', 'Meta', 'Microsoft', 'Goldman Sachs']},
    {'difficulty': 'HARD', 'question_text': 'What are the common C security vulnerabilities and the mitigations against them?', 'expected_answer': 'Common vulnerabilities: buffer overflows (stack and heap), format string bugs (passing user input as the format), integer overflow leading to undersized allocations, use-after- free and double free, uninitialized memory disclosure, off-by-one errors and time-of- check to time-of-use (TOCTOU) races. Mitigations at the platform level: stack canaries, non-executable stack/data (NX/DEP), ASLR, RELRO and control-flow integrity, plus hardened allocators and fortified libc functions (_FORTIFY_SOURCE). At the code level: bounds-checked APIs, validating all external input, avoiding unsafe functions (gets, strcpy), compiling with warnings and sanitizers, fuzzing and using safer languages for new parsing code where possible.', 'companies': ['Microsoft', 'Amazon', 'Google', 'Meta', 'Goldman Sachs', 'Oracle']},
    {'difficulty': 'HARD', 'question_text': 'How do you implement information hiding and object-oriented style design in C?', 'expected_answer': 'Use opaque pointers: the header declares a struct type without defining it (typedef struct Foo Foo;) and exposes functions that operate on it, so clients cannot touch fields directly and the layout can change without recompiling them (an ABI-stable interface). Group related functions with a common prefix (a "class"), use constructor and destructor functions to manage lifetime, and implement polymorphism with a struct of function pointers (a hand-written vtable), as in the Linux kernel\'s file operations. Trade- offs: more boilerplate, manual lifetime management and no compiler-enforced type safety for the "inheritance" tricks (embedding a base struct as the first member, with container- of macros).', 'companies': ['Microsoft', 'Amazon', 'Oracle', 'Goldman Sachs', 'Flipkart']},
    {'difficulty': 'HARD', 'question_text': 'What are flexible array members and variable length arrays? What are the issues with VLAs?', 'expected_answer': 'A flexible array member (C99) is an array of unspecified size as the last member of a struct (int data[];); you allocate the struct plus the extra space in one malloc, a common pattern for variable-size messages and buffers. A variable length array (VLA) (C99, optional in C11 and later) has a size determined at run time and lives on the stack. VLAs are dangerous: there is no failure mechanism if the size is too big or negative (stack overflow or UB), they hinder static analysis and some compilers and safety standards disallow them, so prefer heap allocation or fixed bounds with explicit checks.', 'companies': ['Google', 'Microsoft', 'Amazon', 'Goldman Sachs']},
    {'difficulty': 'HARD', 'question_text': 'How has C evolved across standards (C89, C99, C11, C17, C23)?', 'expected_answer': 'C89/C90 (ANSI) standardized the language and library. C99 added // comments, inline, restrict, mixed declarations and statements, long long, <stdint.h>, <stdbool.h>, VLAs, designated initializers, compound literals and flexible array members. C11 added the memory model with <stdatomic.h> and <threads.h>, _Generic, _Static_assert, anonymous structs and _Alignas, and made VLAs and threads optional; it also removed gets. C17 is a bug-fix revision. C23 adds nullptr, bool, true and false as keywords, constexpr for objects, typeof, binary literals and digit separators, #embed, <stdbit.h> and checked integer arithmetic, and deprecates old-style function declarations. Know which standard your target compiler and platform supports.', 'companies': ['Oracle', 'Microsoft', 'Zoho', 'Goldman Sachs', 'Amazon']},
    {'difficulty': 'HARD', 'question_text': 'How do setjmp and longjmp work, and what are their pitfalls?', 'expected_answer': 'setjmp saves the current execution context (registers and stack pointer) in a jmp_buf and returns 0; longjmp restores it so execution continues as if setjmp returned again with a non-zero value, giving a non-local jump used for error handling and coroutines-like control flow. Pitfalls: it skips normal cleanup, so resources (memory, locks, open files) leak; local variables modified after setjmp and not declared volatile have indeterminate values after the jump; jumping into a function that has already returned is undefined behavior; and it interacts badly with signal masks and threads. Disciplined error handling with return codes and cleanup labels is usually clearer.', 'companies': ['Oracle', 'Microsoft', 'Goldman Sachs', 'Google']},
    {'difficulty': 'HARD', 'question_text': 'How do CPU caches and memory access patterns affect C performance? What is memory-mapped I/O?', 'expected_answer': 'Memory access dominates the performance of many programs. Sequential access over contiguous arrays exploits spatial locality and hardware prefetching, while pointer chasing through linked structures causes cache misses; iterating a 2D array in the wrong order (against row-major layout) is a classic slowdown. Struct of arrays versus array of structs layouts, keeping hot data small and aligned, and avoiding false sharing (independent variables on the same cache line written by different threads) are common optimizations. In embedded and driver code, memory-mapped I/O exposes hardware registers at fixed addresses, which must be accessed through volatile pointers, with care for access width, read side effects and memory barriers. Always measure with a profiler first.', 'companies': ['Goldman Sachs', 'Google', 'Meta', 'Amazon', 'Microsoft']},
    {'difficulty': 'HARD', 'question_text': 'How are floating-point numbers represented (IEEE 754)? Why can comparisons go wrong?', 'expected_answer': "float and double use sign, exponent and mantissa fields (32 and 64 bits), so most decimal fractions (0.1) cannot be represented exactly and arithmetic rounds at each step: the order of operations changes results and equality comparison is unreliable, so compare with a tolerance (absolute and relative) or use integers (such as cents) for money. Special values include infinities, NaN (which is not equal to itself, so x != x detects it) and signed zero. Overflow, underflow and denormals have performance and precision implications, and the compiler's floating-point flags (-ffast-math) can change semantics. float promotes to double in variadic calls and, depending on the platform, intermediate precision may be wider than the type.", 'companies': ['Goldman Sachs', 'Google', 'Microsoft', 'Amazon', 'Zoho']},
    {'difficulty': 'HARD', 'question_text': 'What constraints define embedded and real-time C programming (interrupts, ISRs, RTOS, memory limits)?', 'expected_answer': 'Embedded systems have limited RAM and flash, no or little OS, and often hard timing requirements. Typical practices: static allocation or fixed-size pools instead of the heap (no fragmentation or unpredictable latency), no recursion or bounded stack depth, fixed- width types, volatile for hardware and shared interrupt data, and careful interrupt service routines (ISRs) that are short, avoid blocking and non-reentrant calls, and communicate through flags or queues. An RTOS provides tasks, priorities, semaphores, mutexes (with priority inheritance to avoid priority inversion), queues and timers; deterministic worst-case timing matters more than average speed. Coding standards such as MISRA C restrict risky language features, and watchdog timers, power management and fault handling are part of the design.', 'companies': ['Amazon', 'Microsoft', 'Goldman Sachs', 'Oracle', 'Google']},
    {'difficulty': 'HARD', 'question_text': 'How do you debug and verify C programs? Which tools matter and what is MISRA C?', 'expected_answer': 'Tools: a debugger (gdb or lldb) for breakpoints, watchpoints, backtraces and core dump analysis; Valgrind and sanitizers (AddressSanitizer, UndefinedBehaviorSanitizer, MemorySanitizer, ThreadSanitizer, LeakSanitizer) for memory, UB and race errors; static analyzers (clang-tidy, cppcheck, Coverity) and compiler warnings treated as errors; fuzzers (AFL, libFuzzer) for parsers and input handling; strace / ltrace and profilers (perf, gprof). Good practice includes unit tests, assertions, defensive coding, code review and running continuous integration with sanitizers on. MISRA C is a widely used coding guideline for safety-critical systems (automotive, aerospace) that forbids or restricts error-prone constructs such as dynamic memory, recursion, and implicit conversions.', 'companies': ['Google', 'Microsoft', 'Amazon', 'Goldman Sachs', 'Oracle', 'Meta']},
]


def seed_c_questions() -> None:
    db = SessionLocal()
    try:
        topic = db.query(Topic).filter(Topic.name == TOPIC_NAME).first()

        if topic is None:
            raise RuntimeError(
                "The C topic does not exist. Create the C topic in the app/database first; "
                "this seeder will not create a duplicate topic."
            )

        if not topic.is_active:
            raise RuntimeError(
                f"The C topic (ID: {topic.id}) is inactive. Activate it first."
            )

        existing_count = db.query(Question).filter(Question.topic_id == topic.id).count()
        if existing_count > 0:
            print(f"C topic (ID: {topic.id}) already contains {existing_count} question(s).")
            print("No questions were inserted to avoid duplicates.")
            print("Inspect existing C questions before deciding whether to seed again.")
            return

        difficulty_map = {
            "EASY": QuestionDifficulty.EASY,
            "MEDIUM": QuestionDifficulty.MEDIUM,
            "HARD": QuestionDifficulty.HARD,
        }

        records = [
            Question(
                topic_id=topic.id,
                difficulty=difficulty_map[item["difficulty"]],
                question_text=item["question_text"],
                expected_answer=item["expected_answer"],
                companies=item["companies"],
            )
            for item in QUESTIONS
        ]

        db.add_all(records)
        db.commit()

        counts = Counter(item["difficulty"] for item in QUESTIONS)
        print("=" * 60)
        print("C THEORY QUESTION BANK CREATED")
        print("=" * 60)
        print(f"Topic ID        : {topic.id}")
        print(f"Topic           : {topic.name}")
        print(f"Total questions : {len(records)}")
        print(f"Easy            : {counts['EASY']}")
        print(f"Medium          : {counts['MEDIUM']}")
        print(f"Hard            : {counts['HARD']}")
        print("Company tags    : Stored in the companies JSON column")
        print("=" * 60)

    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


if __name__ == "__main__":
    seed_c_questions()
